INSERT OR REPLACE INTO ec_page_services ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "cta_title", "cta_sub", "heading", "intro", "pricing_heading", "pricing_sub", "pricing_footnote", "addons_heading", "why_heading", "why_sub", "why_items", "why_closing", "faq_heading", "faq_sub", "faq") VALUES ('01CIA851E409FCE4B83F181C2D', 'services', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIA851E409FCE4B83F181C2D', 'Services', 'Strategy, web design, and brand work for clients anywhere, plus photography across the greater Cincinnati region. Based in Cincinnati.', 'Ready to scope a project?', 'The first conversation is free and lands at an honest ballpark by the end. Email is fastest, but a phone call works too.', 'Strategy, web design, and photography for organizations that care about the long run.', 'Most projects use all three services, in that order. Some use one or two. The first conversation always ends with an honest scope, not a sales pitch.', 'What a website costs', 'A starting point, not a fixed menu. Every build is custom and comes with a content system you can run yourself, so the tiers differ in scope and how much functionality you need, not whether the work is custom. The free first conversation ends with an honest ballpark, and larger projects can be split into monthly payments.', 'Strategy is the front of every project, not a line item. The price above already includes the session and the brief.', 'Add to any project', 'Why it costs what it costs', 'Plenty of people will quote you less. Here is what the price actually buys, and what a cheaper one usually leaves out.', '[{"title":"One person, no handoffs","body":"The person who plans your site designs it, builds it, and shoots the photos. No agency markup, and nothing lost in translation between a strategist, a designer, and a developer who never quite talk to each other."},{"title":"Built to be handed off","body":"Every site is set up so the next volunteer or staff member can keep it running, and you own it outright. A cheaper site that leaves you stranded the day the freelancer goes quiet costs far more to replace than it saved."},{"title":"Accessible by default","body":"Every page meets WCAG AA and scores 100 for accessibility. Most budget builds fail this badly. For a church, school, or nonprofit it is both the right thing to do and real legal cover, included, not an upsell."},{"title":"Cheap is expensive later","body":"A bargain site quietly runs into thousands a year once you bolt on the features it could not handle up front. I would rather build it once, on a stack that is nearly free to run and is yours to keep."}]', 'I build with modern tools, including AI-assisted workflows, the same way I use frameworks and a camera. They help one person do the work of a team. The strategy, the design, and the accountability stay mine, start to finish.', 'Common questions', 'The things people ask before the first call.', '[{"question":"What does it cost?","answer":"Websites start at $4,000 for a focused Launch site. Most projects land between $7,000 and $11,000, and builds with real custom functionality start around $12,000. Every build is custom and comes with a content system you can manage yourself; what moves the number is scope, functionality, photography, and content. The first conversation is free and ends with an honest ballpark before either of us is committed, and larger projects can be split into monthly payments so the budget is about cash flow, not one big wall."},{"question":"What if I have been quoted less somewhere else?","answer":"You probably can find a cheaper quote, and for a very simple need that might be the right call. What a low quote usually leaves out is the part that matters later: accessibility, a content system your team can actually run, a plan for who maintains the site after launch, and someone who still answers the phone in a year. A site you have to rebuild in eighteen months is the expensive one. I would rather build it once."},{"question":"How long does a typical project take?","answer":"Most websites land between six and ten weeks from kickoff to launch. Larger projects with custom photography or multiple content collections can run twelve to sixteen weeks. The brief at the end of strategy sets the real timeline."},{"question":"Do you offer maintenance?","answer":"Optional. After launch you own the site outright and can leave it alone for years if nothing breaks. If you want hands-on support, care plans start at $100 a month for updates, backups, and security, with higher tiers that add a monthly bucket of content edits."},{"question":"Can you work with my existing brand?","answer":"Yes. If you already have a logo, palette, and type system, we use it. If you do not, brand work can be folded into the strategy phase or scoped separately."},{"question":"Where are you based, and do you work with clients outside Cincinnati?","answer":"I''m based in Cincinnati, but web design, strategy, and brand work happen with clients anywhere, fully remote when that is easier. Photography is the one piece that needs me on site, so that stays within the greater Cincinnati region."}]');
