INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "sort_order") VALUES ('01CIE4B1B487667A56E6DED974', 'launch', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIE4B1B487667A56E6DED974', 'Launch', 4000, '+', 'Smaller organizations', 'Most land between $4,000 and $6,500', 'A focused custom site for a smaller organization: the essential pages done well, with content you can keep current yourself. The right fit when you want a clear, strong presence without a lot of moving parts.', '[{"text":"A focused set of core pages, designed around your goals"},{"text":"Content you can keep current yourself"},{"text":"Accessible and fast, set up and handed off"}]', 0, 1);
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "badge", "sort_order") VALUES ('01CI8EA3C2DC72783758A801AB', 'signature', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI8EA3C2DC72783758A801AB', 'Signature', 7000, '+', 'Most projects', 'Most land between $7,000 and $11,000', 'The right fit for most projects: a larger custom site with deeper content, several content types your team manages itself, and the integrations a growing church, school, or business needs.', '[{"text":"A larger site with deeper content sections"},{"text":"Several content types your team manages itself"},{"text":"Integrations and search-engine work built in"}]', 1, 'Where most projects land', 2);
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "sort_order") VALUES ('01CI31FAD2736752DFADAF1AB0', 'flagship', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI31FAD2736752DFADAF1AB0', 'Flagship', 12000, '+', 'Advanced builds', 'Typically $12,000 and up', 'For organizations that need the site to do real work: custom interactive tools, advanced integrations, or a headless build for a large, complex site. The kind of build an agency would charge far more for.', '[{"text":"Custom interactive tools and features"},{"text":"Advanced and third-party integrations"},{"text":"A headless build for a large, deep site"}]', 0, 3);
